/// <summary>
/// Controller class for the METCoverNote report
/// </summary>
class METCoverNoteController extends SrsReportRunController
{
}

Method.Source:
    /// <summary>
    /// Handles the logic of priniting the report
    /// </summary>
    /// <param name = "_args">controller args</param>
    static void main(Args _args)
    {
        METCoverNoteController controller;

        controller = new METCoverNoteController();
        controller.parmReportName(ssrsReportStr(METCoverNote, Report));
        controller.parmDialogCaption("@MET:CoverNote");
        controller.parmArgs(_args);

        METCoverNoteContract contract = controller.parmReportContract().parmRdpContract();

        if(_args.dataset() == tableNum(METShipmentTable))
        {
            METShipmentTable metShipmentTable = _args.record();
            if(metShipmentTable)
            {
                contract.parmShipmentId(metShipmentTable.ShipmentId);
            }
        }
        controller.startOperation();
    }
